  "rubrics": [
    {
      "criterion": "The response provides a concise, step‑by‑step instruction for changing the default application of common file types (e.g., .js, .ts, .json) to Visual Studio Code using macOS Finder’s Get Info interface, including 1) selecting the file type, 2) opening Get Info (Cmd‑I or right‑click > Get Info), 3) expanding the ‘Open with’ section, 4) choosing Visual Studio Code from the drop‑down, 5) clicking ‘Change All…’, and 6) confirming with a password if prompted.",
      "weight": 5,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response includes the exact Terminal command to open a single file with VS Code: ‘open -a 'Visual Studio Code' <file>’, and explains the syntax and how to use it.",
      "weight": 3,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response explains the purpose of selecting ‘Change All…’ and describes its effect on setting the default application for that file extension across all files.",
      "weight": 4,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response acknowledges that a password may be required to confirm the change and advises the user to prepare for the administrator prompt.",
      "weight": 2,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response recommends enabling ‘Show all filename extensions’ in Finder > Preferences > Advanced to prevent hidden extensions from causing incorrect associations.",
      "weight": 1,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response advises the user to repeat the process for each file type they wish to associate with VS Code, listing examples such as .js, .ts, and .json.",
      "weight": 2,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response integrates the Finder-based steps with the Terminal command, demonstrating how the two methods complement each other for quick file opening.",
      "weight": 3,
      "axis": "Synthesis of Information"
    },
    {
      "criterion": "The response compares the quick default‑binding method to manually selecting VS Code via right‑click > Open With for a single file, highlighting the convenience of the former.",
      "weight": 2,
      "axis": "Synthesis of Information"
    },
    {
      "criterion": "The response cites macOS Help or Apple Support documentation as a source for the Get Info procedure, providing a reference URL.",
      "weight": 2,
      "axis": "References & Citation Quality"
    },
    {
      "criterion": "The response includes a citation to VS Code documentation for the Terminal command syntax, with a reference to the VS Code official docs.",
      "weight": 1,
      "axis": "References & Citation Quality"
    },
    {
      "criterion": "The response uses clear, sequential numbering for each step, making it easy to follow and allowing for quick replication.",
      "weight": 2,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response provides a brief introductory paragraph that summarizes the overall goal of binding file types to VS Code.",
      "weight": 1,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response explicitly lists the correct order of operations: open Get Info, expand ‘Open with’, choose VS Code, click ‘Change All…’, confirm password.",
      "weight": 5,
      "axis": "Instruction Following"
    },
    {
      "criterion": "The response explicitly states that a password confirmation dialog may appear the first time the change is made.",
      "weight": 3,
      "axis": "Instruction Following"
    },
    {
      "criterion": "The response fails to mention selecting Visual Studio Code from the dropdown in the ‘Open with’ section.",
      "weight": -5,
      "axis": "Explicit Criteria"
    },
    {
      "criterion": "The response omits confirming the action with a password if prompted, implying the operation is painless.",
      "weight": -3,
      "axis": "Implicit Criteria"
    },
    {
      "criterion": "The response gives contradictory instructions, such as recommending not to use ‘Change All…’ while still instructing the user to apply the change to all files.",
      "weight": -4,
      "axis": "Synthesis of Information"
    },
    {
      "criterion": "The response displays all steps in a single paragraph without numbering or bullets, reducing readability and hindering follow‑through.",
      "weight": -2,
      "axis": "Communication Quality"
    },
    {
      "criterion": "The response cites non‑Apple sources for Get Info steps, potentially leading to misinformation about the correct procedure.",
      "weight": -3,
      "axis": "References & Citation Quality"
    },
    {
      "criterion": "The response assumes the user has an existing VS Code .app in /Applications but does not address locating it if it has been moved or renamed.",
      "weight": -4,
      "axis": "Instruction Following"
    }
  ]
}

